-- BRANCHING slides (course_id = 19)

UPDATE acc_training_slides SET interactive_config = '{"type":"scenario","instruction":"A form has a Gender field (Male/Female) and a Pregnancy Test Date field that should only appear for females. How do you configure this?","data":{"context":"You need Pregnancy Test Date to be visible only when Gender = Female.","choices":[{"text":"Add a validation rule to block save if Gender is Male and date is filled","correct":false,"feedback":"Validation rules check values after entry. Branching logic prevents the field from showing at all."},{"text":"Add a show/hide condition: Show Pregnancy Test Date when Gender equals Female","correct":true,"feedback":"Correct! Add a branching condition on the Pregnancy Test Date field with controlling field = Gender, operator = equals, value = Female."},{"text":"Create two separate forms, one for each gender","correct":false,"feedback":"This creates unnecessary duplication. Branching logic handles conditional display within a single form."},{"text":"Make it required and tell male patients to enter N/A","correct":false,"feedback":"This is poor UX and creates dirty data. Use branching to hide irrelevant fields."}]},"successMessage":"You correctly identified how to use show/hide branching!"}'
WHERE course_id = 19 AND order_index = 4;

UPDATE acc_training_slides SET interactive_config = '{"sectionTitle":"Branching Logic","questions":[{"id":"br-1","question":"Branching logic can show/hide fields based on values in other fields.","type":"true-false","options":["True","False"],"correctIndex":0,"explanation":"That is the primary purpose of branching logic."},{"id":"br-2","question":"What happens to hidden field values when the form is submitted?","type":"multiple-choice","options":["They are saved with their last value","They are cleared and not submitted","They cause a validation error","They are converted to null"],"correctIndex":1,"explanation":"Hidden fields are cleared and not included in the submission."},{"id":"br-3","question":"Multiple show conditions on a field use what logic?","type":"multiple-choice","options":["AND (all must be true)","OR (any can be true)","XOR (exactly one must be true)","NOT (none can be true)"],"correctIndex":1,"explanation":"Multiple conditions use OR logic — field shows if ANY condition is met."}]}'
WHERE course_id = 19 AND slide_type = 'knowledge-check';

